CREATE TABLE IF NOT EXISTS conversation_capture_policies(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,name TEXT NOT NULL,channel TEXT NOT NULL CHECK(channel IN('PHONE_CALL','FRONT_DESK_AMBIENT')),enabled INTEGER NOT NULL DEFAULT 0,consent_mode TEXT NOT NULL DEFAULT 'ALL_PARTY_NOTICE_AND_CONSENT',notice_text TEXT NOT NULL,retention_days INTEGER NOT NULL DEFAULT 30,raw_audio_retained INTEGER NOT NULL DEFAULT 0,transcript_retained INTEGER NOT NULL DEFAULT 1,redaction_enabled INTEGER NOT NULL DEFAULT 1,legal_review_status TEXT NOT NULL DEFAULT 'REQUIRED',legal_review_reference TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,channel));
CREATE TABLE IF NOT EXISTS conversation_capture_sessions(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,policy_id TEXT NOT NULL,channel TEXT NOT NULL,source_reference TEXT,started_by TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT,recording_indicator_active INTEGER NOT NULL DEFAULT 1,consent_status TEXT NOT NULL DEFAULT 'PENDING',status TEXT NOT NULL DEFAULT 'AWAITING_CONSENT',audio_object_key TEXT,audio_sha256 TEXT,transcript_object_key TEXT,transcript_status TEXT NOT NULL DEFAULT 'NOT_STARTED',retention_delete_at TEXT,legal_hold INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(policy_id) REFERENCES conversation_capture_policies(id));
CREATE TABLE IF NOT EXISTS conversation_consent_events(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,participant_label TEXT NOT NULL,notice_method TEXT NOT NULL,response TEXT NOT NULL,recorded_by TEXT NOT NULL,recorded_at TEXT NOT NULL,evidence_json TEXT NOT NULL DEFAULT '{}',FOREIGN KEY(session_id) REFERENCES conversation_capture_sessions(id));
CREATE TABLE IF NOT EXISTS conversation_intelligence_findings(id TEXT PRIMARY KEY,session_id TEXT NOT NULL,finding_type TEXT NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,confidence REAL NOT NULL DEFAULT 0,risk_level TEXT NOT NULL DEFAULT 'REVIEW',status TEXT NOT NULL DEFAULT 'DRAFT',approval_status TEXT NOT NULL DEFAULT 'PENDING',operational_record_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(session_id) REFERENCES conversation_capture_sessions(id));
CREATE INDEX IF NOT EXISTS idx_capture_session_scope ON conversation_capture_sessions(organization_id,property_id,status,started_at);
CREATE INDEX IF NOT EXISTS idx_capture_findings_session ON conversation_intelligence_findings(session_id,status);
